import { mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { writeFileAtomic } from "../core/atomic.js";
import type { CobPaths } from "./paths.js";

export type ProfileInput = {
  port: number;
  catalogPath: string;
};

export function renderCobProfile(input: ProfileInput): string {
  const baseUrl = `http://127.0.0.1:${input.port}/v1`;
  return [
    "# Generated by cob. Do not point this profile at a custom model_provider.",
    "# Launch Codex with: codex --profile cob",
    `model_provider = "openai"`,
    `openai_base_url = ${tomlString(baseUrl)}`,
    `model_catalog_json = ${tomlString(input.catalogPath)}`,
    "",
    "[features]",
    "multi_agent_v2 = false",
    "remote_compaction_v2 = true",
    "",
  ].join("\n");
}

export function writeCobProfile(paths: CobPaths, port: number): void {
  mkdirSync(dirname(paths.profile), { recursive: true });
  writeFileAtomic(paths.profile, renderCobProfile({ port, catalogPath: paths.catalog }), 0o600);
}

function tomlString(value: string): string {
  return JSON.stringify(value);
}
